class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;

    long[] dp;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int MAX = 100005;
        long MAX2 = (long)1e18 + 10;

        dp = new long[MAX];
        dp[0] = f0.Length;
        for (int i = 1; i < MAX; i++)
        {
            if (dp[i - 1] > MAX2 / 2)
            {
                dp[i] = MAX2;
            }
            else
            {
                dp[i] = dp[i - 1] * 2 + s0.Length + s1.Length + s2.Length;
            }

        }

        for (int i = 0; i < N; i++)
        {
            a = cin.nextInt();
            b = cin.nextLong() - 1;

            while (a != -1) dfs();
            Console.Write(c);

        }
        Console.WriteLine();
    }

    int a;
    long b;
    char c = '.';

    string f0 = "What are you doing at the end of the world? Are you busy? Will you save us?";
    string s0 = "What are you doing while sending \"";
    string s1 = "\"? Are you busy? Will you send \"";
    string s2 = "\"?";

    void dfs()
    {
        if (b >= dp[a])
        {
            c = '.'; a = -1;
            return;
        }
        if(a == 0)
        {
            c = f0[(int)b]; a = -1;
            return;
        }
        if (b < s0.Length)
        {
            c = s0[(int)b]; a = -1;
            return;
        }
        b -= s0.Length;
        if (b < dp[a - 1])
        {
            a--;
            return;
        }
        b -= dp[a - 1];
        if (b < s1.Length)
        {
            c = s1[(int)b]; a = -1;
            return;
        }
        b -= s1.Length;
        if (b < dp[a - 1])
        {
            a--;
            return;
        }
        b -= dp[a - 1];
        c = s2[(int)b];
        a = -1;
        return;
    }
}



class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextInt() + add;
        }
        return Array;
    }

    public long nextLong()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextLong() + add;
        }
        return Array;
    }

    public double nextDouble()
    {
        return double.Parse(next());
    }


    public double[] ArrayDouble(int N, double add = 0)
    {
        double[] Array = new double[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextDouble() + add;
        }
        return Array;
    }
}
